function [dx, thrust, m] = propagateFopt_SEP_MEXIFY( t, xvalues, pp )

mu       = pp(1);
Tmax_1AU = pp(2); % --> this is at 1 AU
IspScl   = pp(3);
g0Scl    = pp(4);
rho      = pp(5);

scaling_dist = pp(6);
scaling_time = pp(7);
scaling_mass = pp(8);

thrust_max_N = pp(9);
n_engines    = pp(10);
epsilon      = pp(11);


p           = xvalues(1);
f           = xvalues(2);
g           = xvalues(3); 
h           = xvalues(4);
k           = xvalues(5);
L           = xvalues(6);
m           = xvalues(7);
lambda_rx   = xvalues(8);
lambda_ry   = xvalues(9);
lambda_rz   = xvalues(10);
lambda_vx   = xvalues(11);
lambda_vy   = xvalues(12);
lambda_vz   = xvalues(13);
lambda_m    = xvalues(14);

cosL        = cos(L);
sinL        = sin(L);
sqrt_p_mu   = sqrt(p/mu);
q           = 1+f*cosL+g*sinL; 
s2          = 1 + h^2 + k^2; 
A           = [ 0 0 0 0 0 sqrt(mu*p)*(q/p)^2]';

B = [0                      2*p/q*sqrt_p_mu                0;
    sqrt_p_mu*sinL  sqrt_p_mu/q*((q+1)*cosL+f) -sqrt_p_mu*g/q*(h*sinL-k*cosL);
    -sqrt_p_mu*cosL sqrt_p_mu*1/q*((q+1)*sinL+g) sqrt_p_mu*f/q*(h*sinL-k*cosL);
    0                      0                                   sqrt_p_mu*s2*cosL/(2*q);
    0                      0                                   sqrt_p_mu*s2*sinL/(2*q);
    0                      0                                   sqrt_p_mu*(h*sinL-k*cosL)/q];


% --> start: fuel-optimal control
radius    = p / q;

% epsilon              = 0.002; % --> adjust this to best fit your curve
scaling_param_thrust = scaling_time^2/scaling_mass/1000/scaling_dist;

Tmax_1AU_N           = Tmax_1AU / scaling_param_thrust;
func_1               = Tmax_1AU_N ./ radius.^2 ;
func_2               = n_engines * thrust_max_N;
TmaxScl              = -epsilon.*log( exp( -(func_1)./epsilon ) + exp( -(func_2)./epsilon ) ) * scaling_param_thrust;

S           = (g0Scl*IspScl/m) * norm(B'*xvalues(8:13)) + lambda_m - 1;
sigmaStar   = 0.5 * ( 1 + tanh( S/rho ) );

if sum(xvalues(8:13)) ~= 0
    uStar = -B'*xvalues(8:13)/(norm(B'*xvalues(8:13)));
else
    uStar = [0;0;0];
end

uuStar = sigmaStar.*uStar;
u1     = uStar(1);
u2     = uStar(2);
u3     = uStar(3);
thrust = TmaxScl*uuStar;
% --> end: fuel-optimal control

% --> dynamics
dx          = zeros( 14,1 );
dx(1:6,1)   = A + (TmaxScl/m)*B*uuStar;                                             % --> states
dx(7,1)     = -TmaxScl/( g0Scl*IspScl )*sigmaStar;    % --> mass

c            = g0Scl*IspScl;
sigma        = sigmaStar;

dx(8,1)  = lambda_rz*((epsilon*scaling_param_thrust*sigma*u1*log(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon))*cos(L))/(2*m*mu*(p/mu)^(1/2)) - (epsilon*scaling_param_thrust*sigma*u2*log(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon))*(g + sin(L)*(f*cos(L) + g*sin(L) + 2)))/(2*m*mu*(p/mu)^(1/2)*(f*cos(L) + g*sin(L) + 1)) + (2*Tmax_1AU_N*scaling_param_thrust*sigma*u1*exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2))*cos(L)*(p/mu)^(1/2)*(f*cos(L) + g*sin(L) + 1)^2)/(m*p^3*(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon))) - (2*Tmax_1AU_N*scaling_param_thrust*sigma*u2*exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2))*(g + sin(L)*(f*cos(L) + g*sin(L) + 2))*(p/mu)^(1/2)*(f*cos(L) + g*sin(L) + 1))/(m*p^3*(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon))) + (epsilon*f*scaling_param_thrust*sigma*u3*log(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon))*(k*cos(L) - h*sin(L)))/(2*m*mu*(p/mu)^(1/2)*(f*cos(L) + g*sin(L) + 1)) + (2*Tmax_1AU_N*f*scaling_param_thrust*sigma*u3*exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2))*(k*cos(L) - h*sin(L))*(p/mu)^(1/2)*(f*cos(L) + g*sin(L) + 1))/(m*p^3*(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon)))) - lambda_ry*((epsilon*scaling_param_thrust*sigma*u1*log(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon))*sin(L))/(2*m*mu*(p/mu)^(1/2)) + (epsilon*scaling_param_thrust*sigma*u2*log(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon))*(f + cos(L)*(f*cos(L) + g*sin(L) + 2)))/(2*m*mu*(p/mu)^(1/2)*(f*cos(L) + g*sin(L) + 1)) + (2*Tmax_1AU_N*scaling_param_thrust*sigma*u1*exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2))*sin(L)*(p/mu)^(1/2)*(f*cos(L) + g*sin(L) + 1)^2)/(m*p^3*(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon))) + (2*Tmax_1AU_N*scaling_param_thrust*sigma*u2*exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2))*(f + cos(L)*(f*cos(L) + g*sin(L) + 2))*(p/mu)^(1/2)*(f*cos(L) + g*sin(L) + 1))/(m*p^3*(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon))) + (epsilon*g*scaling_param_thrust*sigma*u3*log(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon))*(k*cos(L) - h*sin(L)))/(2*m*mu*(p/mu)^(1/2)*(f*cos(L) + g*sin(L) + 1)) + (2*Tmax_1AU_N*g*scaling_param_thrust*sigma*u3*exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2))*(k*cos(L) - h*sin(L))*(p/mu)^(1/2)*(f*cos(L) + g*sin(L) + 1))/(m*p^3*(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon)))) + lambda_vz*((conj(mu)*(cos(conj(L))*conj(f) + sin(conj(L))*conj(g) + 1)^2)/(2*conj(p)^2*conj((mu*p)^(1/2))) - (2*conj((mu*p)^(1/2))*(cos(conj(L))*conj(f) + sin(conj(L))*conj(g) + 1)^2)/conj(p)^3 + (epsilon*scaling_param_thrust*sigma*u3*log(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon))*(k*cos(L) - h*sin(L)))/(2*m*mu*(p/mu)^(1/2)*(f*cos(L) + g*sin(L) + 1)) + (2*Tmax_1AU_N*scaling_param_thrust*sigma*u3*exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2))*(k*cos(L) - h*sin(L))*(p/mu)^(1/2)*(f*cos(L) + g*sin(L) + 1))/(m*p^3*(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon)))) - (2*Tmax_1AU_N*scaling_param_thrust*sigma*exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2))*(f*cos(L) + g*sin(L) + 1)^2)/(c*p^3*(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon))) + (2*Tmax_1AU_N*lambda_m*scaling_param_thrust*sigma*exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2))*(f*cos(L) + g*sin(L) + 1)^2)/(c*p^3*(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon))) - (2*epsilon*lambda_rx*scaling_param_thrust*sigma*u2*log(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon))*(p/mu)^(1/2))/(m*(f*cos(L) + g*sin(L) + 1)) - (4*Tmax_1AU_N*lambda_rx*scaling_param_thrust*sigma*u2*exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2))*(p/mu)^(1/2)*(f*cos(L) + g*sin(L) + 1))/(m*p^2*(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon))) - (epsilon*lambda_rx*p*scaling_param_thrust*sigma*u2*log(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon)))/(m*mu*(p/mu)^(1/2)*(f*cos(L) + g*sin(L) + 1)) - (epsilon*lambda_vx*scaling_param_thrust*sigma*u3*log(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon))*cos(L)*(h^2 + k^2 + 1))/(2*m*mu*(p/mu)^(1/2)*(2*f*cos(L) + 2*g*sin(L) + 2)) - (epsilon*lambda_vy*scaling_param_thrust*sigma*u3*log(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon))*sin(L)*(h^2 + k^2 + 1))/(2*m*mu*(p/mu)^(1/2)*(2*f*cos(L) + 2*g*sin(L) + 2)) - (2*Tmax_1AU_N*lambda_vx*scaling_param_thrust*sigma*u3*exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2))*cos(L)*(p/mu)^(1/2)*(f*cos(L) + g*sin(L) + 1)^2*(h^2 + k^2 + 1))/(m*p^3*(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon))*(2*f*cos(L) + 2*g*sin(L) + 2)) - (2*Tmax_1AU_N*lambda_vy*scaling_param_thrust*sigma*u3*exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2))*sin(L)*(p/mu)^(1/2)*(f*cos(L) + g*sin(L) + 1)^2*(h^2 + k^2 + 1))/(m*p^3*(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon))*(2*f*cos(L) + 2*g*sin(L) + 2));
dx(9,1)  = lambda_ry*((epsilon*scaling_param_thrust*sigma*u2*log(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon))*cos(L)*(f + cos(L)*(f*cos(L) + g*sin(L) + 2))*(p/mu)^(1/2))/(m*(f*cos(L) + g*sin(L) + 1)^2) - (epsilon*scaling_param_thrust*sigma*u2*log(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon))*(cos(L)^2 + 1)*(p/mu)^(1/2))/(m*(f*cos(L) + g*sin(L) + 1)) + (2*Tmax_1AU_N*scaling_param_thrust*sigma*u2*exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2))*cos(L)*(f + cos(L)*(f*cos(L) + g*sin(L) + 2))*(p/mu)^(1/2))/(m*p^2*(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon))) + (epsilon*g*scaling_param_thrust*sigma*u3*log(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon))*cos(L)*(k*cos(L) - h*sin(L))*(p/mu)^(1/2))/(m*(f*cos(L) + g*sin(L) + 1)^2) + (2*Tmax_1AU_N*g*scaling_param_thrust*sigma*u3*exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2))*cos(L)*(k*cos(L) - h*sin(L))*(p/mu)^(1/2))/(m*p^2*(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon))) + (2*Tmax_1AU_N*scaling_param_thrust*sigma*u1*exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2))*cos(L)*sin(L)*(p/mu)^(1/2)*(f*cos(L) + g*sin(L) + 1))/(m*p^2*(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon)))) - lambda_rz*((epsilon*scaling_param_thrust*sigma*u2*log(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon))*cos(L)*sin(L)*(p/mu)^(1/2))/(m*(f*cos(L) + g*sin(L) + 1)) - (epsilon*scaling_param_thrust*sigma*u2*log(exp(-(Tmax_1AU_N*(f*cos(L) + g*sin(L) + 1)^2)/(epsilon*p^2)) + exp(-(n_engines*thrust_max_N)/epsilon))*cos(L)*(g + sin(L)*(f*cos(L) + g*sin(L) + 2))*(p/mu)^(1/2))/(m*(f*cos(L) + g*sin(L) + 1)^2) - (epsilon*scaling_param_thrust*si